-- Append-only state-machine transition log, as generated by popular
-- state-machine libraries: one row per transition, UNIQUE(parent, sort_key)
-- for ordering, and a partial unique index guaranteeing a single
-- most_recent transition per parent.
DROP TABLE IF EXISTS payment_transitions CASCADE;
CREATE TABLE payment_transitions (
    id          int PRIMARY KEY,
    payment_id  int,
    sort_key    int,
    to_state    text,
    metadata    text,
    most_recent boolean,
    CONSTRAINT payment_transitions_parent_sort_uk UNIQUE (payment_id, sort_key)
);
CREATE UNIQUE INDEX payment_transitions_parent_most_recent_uk
    ON payment_transitions (payment_id) WHERE most_recent;
ALTER TABLE payment_transitions REPLICA IDENTITY FULL;
